insert into collections (slug, title, description, position, bookmark_slugs) values
  ('motion', 'Motion & micro-interactions', 'References and tools for transitions, easing curves and the small details that make an interface feel alive.', 0, array['60fps', 'app-motion-design', 'design-spells', 'easing', 'jitter', 'rive']::text[]),
