insert into posts (slug, title, excerpt, tag, body, bookmark_slugs, published_at) values
  ('color-palette-tools', 'Two tools for every color palette', 'Coolors for finding a direction, UI Colors for turning one hex into a scale an interface can actually use.', 'Color', 'Picking colors is two different jobs. First you need a direction: a mood, a small set of hues that work together. Coolors is built for that — it collects thousands of trending palettes you can browse, save and tweak.
insert into glossary_terms (slug, term, definition, bookmark_slugs) values
  ('ai-art', 'AI art', 'Images created or remixed by machine-learning models from a text prompt or reference pictures.', array['whisk', 'imageprompt']::text[]),
  ('code-screenshot', 'Code screenshot', 'An image of a code snippet, framed and styled for sharing where plain text would lose its formatting.', array['rayso']::text[]),
  ('color-palette', 'Color palette', 'A small, deliberate set of colors used together so an interface or brand feels consistent.', array['coolors', 'ui-colors', 'colorway', 'picular']::text[]),
  ('easing', 'Easing', 'The acceleration curve of an animation — how motion speeds up and slows down instead of moving at a constant rate.', array['easing', '60fps']::text[]),
  ('icon-set', 'Icon set', 'A family of icons drawn on the same grid, stroke and style, so they look consistent side by side.', array['phosphor-icons', 'icon-buddy', '3d-icons', 'thiings']::text[]),
  ('micro-interaction', 'Micro-interaction', 'A small, single-purpose moment of feedback — a like animating, a toggle snapping — that confirms an action.', array['60fps', 'design-spells', 'app-motion-design', 'easing']::text[]),
  ('mockup', 'Mockup', 'A realistic preview of a design placed in context, such as a screenshot inside a device frame.', array['shots', 'brand-bird']::text[]),
  ('pomodoro', 'Pomodoro', 'A focus technique of short, timed work sessions separated by brief breaks.', array['pomofocus']::text[]),
  ('psd', 'PSD', 'Photoshop’s layered file format. Browser editors like Photopea can open and save it.', array['photopea']::text[]),
  ('roadmap', 'Roadmap', 'A step-by-step learning path that shows which skills to pick up, and in what order.', array['roadmaps', 'learn-anything']::text[]),
  ('seo', 'SEO', 'Search engine optimisation: making pages easier for search engines to find, understand and rank.', array['wordstream', 'octopus', 'serpdrill', 'index-guru']::text[]),
  ('typeface', 'Typeface', 'A family of fonts that share one design, such as its regular, medium and bold weights.', array['fontshare', 'uncut']::text[]),
  ('vector', 'Vector', 'Graphics defined by paths and points instead of pixels, so they scale to any size without blurring.', array['vectorpea', 'svgl', 'world-vector-logo']::text[]),
  ('whiteboard', 'Whiteboard', 'A shared, open canvas for sketching diagrams and ideas, often with other people at the same time.', array['excalidraw', 'tldraw', 'witeboard']::text[]),
  ('wireframe', 'Wireframe', 'A low-fidelity layout that shows structure and hierarchy before any visual design is applied.', array['wireframe-examples', 'flowmapp']::text[]);
